#include "fedspatial/gpu_context.hpp"
#include <algorithm>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
using namespace fedspatial;namespace fs=std::filesystem;
static Matrix load(const fs::path&p){Matrix a;if(!read_matrix(p.string(),&a))throw std::runtime_error("missing "+p.string());return a;}static void add(Matrix&a,const Matrix&b){for(int i=0;i<a.rows*a.cols;i++)a.a[i]+=b.a[i];}static void scale(Matrix&a,double s){for(double&v:a.a)v*=s;}static void rows(std::ofstream&o,const char*q,int w,const Matrix&py,const Matrix&cu,double&mx){for(int i=0;i<py.rows;i++)for(int j=0;j<py.cols;j++){double e=std::abs(py(i,j)-cu(i,j));mx=std::max(mx,e);o<<w<<','<<q<<','<<i<<','<<j<<','<<std::setprecision(17)<<py(i,j)<<','<<cu(i,j)<<','<<e<<'\n';}}
int main(){try{fs::path f="sync_gpu/tests/fixtures/figure1_reference",o="results/figure1_cpp_gpu_faithful/parity";fs::create_directories(o);Matrix k=load(f/"knots.txt"),g(5,1),mu(100,1),sig(100,100);double gv[]={-1,2,3,-2,1};for(int i=0;i<5;i++)g(i,0)=gv[i];GlobalParameters p{g,mu,sig,.25,1.,.11};GpuContext c(0);Matrix am(100,1),as(100,100);std::ofstream csv(o/"mu_sigma_p5_parity.csv");csv<<"worker_id,quantity,row,column,python_value,cpp_value,abs_error\n";double em=0,es=0,egm=0,egs=0;for(int w=0;w<10;w++){Matrix d=load(f/("worker_"+std::to_string(w)+".txt"));WorkerInput in{Matrix(100,2),Matrix(100,1),Matrix(100,5)};for(int i=0;i<100;i++){in.sites(i,0)=d(i,0);in.sites(i,1)=d(i,1);in.z(i,0)=d(i,2);for(int q=0;q<5;q++)in.x(i,q)=d(i,3+q);}auto got=compute_mu_sigma_local(c,in,k,p);Matrix pym=load(f/("p_initial_worker_"+std::to_string(w)+"_mu.txt")),pys=load(f/("p_initial_worker_"+std::to_string(w)+"_sigma.txt"));rows(csv,"mu_local",w,pym,got.summary.mu,em);rows(csv,"sigma_local",w,pys,got.summary.sigma,es);add(am,got.summary.mu);add(as,got.summary.sigma);}scale(am,.1);scale(as,.1);Matrix kinv=solve_spd(matern15(k,k,1.,.11),identity(100)),prec=kinv;for(int i=0;i<10000;i++)prec.a[i]+=10*.25*as.a[i];Matrix out_s=solve_spd(prec,identity(100)),out_m=matmul(out_s,am);for(double&v:out_m.a)v*=-2.5;rows(csv,"global_mu",-1,load(f/"p_initial_global_mu.txt"),out_m,egm);rows(csv,"global_sigma",-1,load(f/"p_initial_global_sigma.txt"),out_s,egs);double mx=std::max({em,es,egm,egs});std::cout<<"P5_MU_LOCAL_MAX_ABS_ERROR="<<em<<"\nP5_SIGMA_LOCAL_MAX_ABS_ERROR="<<es<<"\nP5_GLOBAL_MU_MAX_ABS_ERROR="<<egm<<"\nP5_GLOBAL_SIGMA_MAX_ABS_ERROR="<<egs<<"\nP5_MU_SIGMA_PARITY="<<(mx<=1e-10?"PASS":"FAIL")<<"\n";return mx<=1e-10?0:1;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
